# The discount rate is not decided yet. Finance owns it (ticket FIN-12).
# Set this to a fraction (e.g. 0.10 for 10%) once FIN-12 is resolved.
DISCOUNT_RATE = None


def apply_discount(price):
    """Return `price` with the standard discount applied."""
    if DISCOUNT_RATE is None:
        raise ValueError("DISCOUNT_RATE is not set; see ticket FIN-12")
    return price * (1 - DISCOUNT_RATE)
